window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["mastercard"]={html:"<div class=\"own-mastercard\">\n  <header class=\"mc-nav\">\n    <a class=\"mc-logo\" href=\"#\" aria-label=\"Northwind home\">\n      <span class=\"mc-orbit\" aria-hidden=\"true\"><i></i><i></i></span>\n      <span class=\"mc-logo-word\">Northwind</span>\n    </a>\n    <nav class=\"mc-nav-links\" aria-label=\"Primary\">\n      <a href=\"#services\">For you</a>\n      <a href=\"#services\">For business</a>\n      <a href=\"#stories\">Customers</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#footer\">News</a>\n    </nav>\n    <div class=\"mc-nav-right\">\n      <a class=\"mc-cta\" href=\"#pricing\">Get started</a>\n      <button class=\"mc-search\" type=\"button\" aria-label=\"Search\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class=\"mc-hero\" aria-labelledby=\"mcHeroH\">\n    <div class=\"mc-hero-frame\" aria-hidden=\"true\">\n      <div class=\"mc-hero-glass\">\n        <div class=\"mc-hero-bars\">\n          <span style=\"--h:38%\"></span><span style=\"--h:58%\"></span>\n          <span style=\"--h:47%\"></span><span style=\"--h:72%\"></span>\n          <span style=\"--h:63%\"></span><span style=\"--h:88%\"></span>\n          <span style=\"--h:76%\"></span>\n        </div>\n        <div class=\"mc-hero-side\">\n          <b>2.4M</b><span>units</span>\n          <b>14%</b><span>uplift</span>\n          <b>99.2%</b><span>on time</span>\n        </div>\n      </div>\n    </div>\n    <div class=\"mc-hero-copy\">\n      <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Operations analytics</p>\n      <h1 id=\"mcHeroH\" class=\"mc-h1\">See your whole operation, clearly.</h1>\n      <div class=\"mc-hero-two\">\n        <p class=\"mc-lead\">Northwind turns warehouses, regions and pricing into one warm, legible\n          view — every dock, every route, every margin in a single frame.</p>\n        <div class=\"mc-hero-cta\">\n          <a class=\"mc-btn mc-btn-ink\" href=\"#services\">Explore</a>\n          <a class=\"mc-btn mc-btn-ghost\" href=\"#pricing\">Watch the tour</a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"services\" class=\"mc-services\" aria-labelledby=\"mcServH\">\n    <p class=\"mc-ghost\" aria-hidden=\"true\">SERVICES</p>\n    <div class=\"mc-serv-copy\">\n      <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>What Northwind sees</p>\n      <h2 id=\"mcServH\" class=\"mc-h2\">A constellation of operational views.</h2>\n    </div>\n    <div class=\"mc-orbits\" aria-hidden=\"true\">\n      <svg viewBox=\"0 0 1000 420\" preserveAspectRatio=\"none\"><path d=\"M80 300 C 260 140, 420 360, 620 180 S 900 120, 960 90\"/></svg>\n    </div>\n    <div class=\"mc-serv-grid\">\n      <article class=\"mc-portrait-card\">\n        <div class=\"mc-portrait mc-portrait-a\" aria-hidden=\"true\">\n          <a class=\"mc-satellite\" href=\"#\" aria-label=\"Open throughput\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n          </a>\n        </div>\n        <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Throughput</p>\n        <h3 class=\"mc-h3\">Dock, line and cycle time at a glance.</h3>\n      </article>\n      <article class=\"mc-portrait-card mc-offset\">\n        <div class=\"mc-portrait mc-portrait-b\" aria-hidden=\"true\">\n          <a class=\"mc-satellite\" href=\"#\" aria-label=\"Open regions\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n          </a>\n        </div>\n        <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Regions</p>\n        <h3 class=\"mc-h3\">Compare territories without leaving the page.</h3>\n      </article>\n      <article class=\"mc-portrait-card\">\n        <div class=\"mc-portrait mc-portrait-c\" aria-hidden=\"true\">\n          <a class=\"mc-satellite\" href=\"#\" aria-label=\"Open pricing\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14M13 6l6 6-6 6\"/></svg>\n          </a>\n        </div>\n        <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Pricing</p>\n        <h3 class=\"mc-h3\">Margin, discount and tier mix in one card.</h3>\n      </article>\n    </div>\n  </section>\n\n  <section id=\"stories\" class=\"mc-stories\" aria-labelledby=\"mcStorH\">\n    <p class=\"mc-ghost mc-ghost-right\" aria-hidden=\"true\">STORIES</p>\n    <div class=\"mc-stories-head\">\n      <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Proof</p>\n      <h2 id=\"mcStorH\" class=\"mc-h2\">Numbers teams trust.</h2>\n    </div>\n    <div class=\"mc-stories-grid\">\n      <div class=\"mc-stat-card\">\n        <div class=\"mc-stat-row\"><b>2,400</b><span>Sites modelled</span></div>\n        <div class=\"mc-stat-row\"><b>96%</b><span>On-time reporting</span></div>\n        <div class=\"mc-stat-row\"><b>&minus;31%</b><span>Idle dock time</span></div>\n      </div>\n      <figure class=\"mc-quote\">\n        <blockquote><p>&ldquo;We used to reconcile three spreadsheets before the Monday call.\n          Now the region view is the only document we open.&rdquo;</p></blockquote>\n        <figcaption><b>Ada Fenwick</b><span>Director of Logistics, Halden Freight</span></figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <section id=\"pricing\" class=\"mc-pricing\" aria-labelledby=\"mcPriceH\">\n    <div class=\"mc-pricing-head\">\n      <p class=\"mc-eyebrow\"><span class=\"mc-dot\" aria-hidden=\"true\"></span>Plans</p>\n      <h2 id=\"mcPriceH\" class=\"mc-h2\">Priced for every operation.</h2>\n    </div>\n    <div class=\"mc-tiers\">\n      <article class=\"mc-tier\">\n        <h3 class=\"mc-h3\">Depot</h3>\n        <p class=\"mc-tier-price\">$49<span>/mo</span></p>\n        <ul class=\"mc-tier-list\">\n          <li>Up to 5 sites</li><li>Throughput boards</li><li>Email digest</li>\n        </ul>\n        <a class=\"mc-btn mc-btn-ghost mc-btn-block\" href=\"#\">Choose Depot</a>\n      </article>\n      <article class=\"mc-tier mc-tier-featured\">\n        <span class=\"mc-tier-flag\">Most chosen</span>\n        <h3 class=\"mc-h3\">Network</h3>\n        <p class=\"mc-tier-price\">$149<span>/mo</span></p>\n        <ul class=\"mc-tier-list\">\n          <li>Up to 50 sites</li><li>Regional pricing views</li><li>Review &amp; sign-off</li>\n        </ul>\n        <a class=\"mc-btn mc-btn-ink mc-btn-block\" href=\"#\">Choose Network</a>\n      </article>\n      <article class=\"mc-tier\">\n        <h3 class=\"mc-h3\">Fleet</h3>\n        <p class=\"mc-tier-price\">Custom</p>\n        <ul class=\"mc-tier-list\">\n          <li>Unlimited sites</li><li>Dedicated modelling</li><li>Priority support</li>\n        </ul>\n        <a class=\"mc-btn mc-btn-ghost mc-btn-block\" href=\"#\">Talk to sales</a>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"mc-cta\" aria-labelledby=\"mcCtaH\">\n    <h2 id=\"mcCtaH\" class=\"mc-h2\">Start with one board.<br>Grow to every region.</h2>\n    <a class=\"mc-btn mc-btn-ink mc-btn-lg\" href=\"#\">Get started</a>\n  </section>\n\n  <footer id=\"footer\" class=\"mc-foot\">\n    <h2 class=\"mc-foot-head\">We&rsquo;re here whenever operations call.</h2>\n    <div class=\"mc-foot-grid\">\n      <div class=\"mc-foot-col\">\n        <h3>Product</h3>\n        <a href=\"#\">Throughput</a><a href=\"#\">Regions</a><a href=\"#\">Pricing views</a><a href=\"#\">Digests</a>\n      </div>\n      <div class=\"mc-foot-col\">\n        <h3>Solutions</h3>\n        <a href=\"#\">Logistics</a><a href=\"#\">Retail</a><a href=\"#\">Manufacturing</a><a href=\"#\">Public sector</a>\n      </div>\n      <div class=\"mc-foot-col\">\n        <h3>Need help?</h3>\n        <a href=\"#\">Support &nearr;</a><a href=\"#\">Guides &nearr;</a><a href=\"#\">Status</a><a href=\"#\">Contact &nearr;</a>\n      </div>\n      <div class=\"mc-foot-col\">\n        <h3>Company</h3>\n        <a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">News</a><a href=\"#\">Legal</a>\n      </div>\n    </div>\n    <div class=\"mc-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span class=\"mc-foot-small\"><a href=\"#\">Privacy choices</a><a href=\"#\">Terms</a></span>\n      <button class=\"mc-lang\" type=\"button\">English &middot; PH</button>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Mastercard design language ═══════════════\n   Warm putty-cream canvas, one geometric sans at weight 450/500, oversized radii\n   (20 / 40 / 999), circular portraits with white satellite CTAs, traced orbital\n   arcs, ghost watermark headlines, a floating white nav pill and an ink footer. */\n\n.own-mastercard {\n  --cream: #f3f0ee;\n  --lifted: #fcfbfa;\n  --white: #ffffff;\n  --ink: #141413;\n  --charcoal: #262627;\n  --slate: #696969;\n  --granite: #555555;\n  --signal: #cf4500;\n  --signal-light: #f37338;\n  --ghost: #e8e2da;\n  --dust: #d1cdc7;\n  --nav-shadow: rgba(0, 0, 0, .04) 0px 4px 24px 0px;\n  --halo: rgba(0, 0, 0, .08) 0px 24px 48px 0px;\n  --font: 'MarkForMC', 'Sofia Sans', Arial, sans-serif;\n  --gut: clamp(20px, 5cqi, 80px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--cream);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  font-weight: 450;\n  line-height: 1.4;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-mastercard *,\n.own-mastercard *::before,\n.own-mastercard *::after { box-sizing: border-box; }\n.own-mastercard :focus-visible { outline: 2px solid var(--signal); outline-offset: 3px; border-radius: 999px; }\n.own-mastercard .mc-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-h1 { font-weight: 500; font-size: clamp(38px, 5.4cqi, 64px); line-height: 1; letter-spacing: -.02em; }\n.own-mastercard .mc-h2 { font-weight: 500; font-size: clamp(28px, 3.4cqi, 40px); line-height: 1.15; letter-spacing: -.02em; }\n.own-mastercard .mc-h3 { font-weight: 500; font-size: 24px; line-height: 1.2; letter-spacing: -.02em; }\n.own-mastercard .mc-lead { font-weight: 450; font-size: 16px; line-height: 1.4; max-width: 46ch; }\n.own-mastercard .mc-eyebrow { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--granite); }\n.own-mastercard .mc-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--signal); }\n.own-mastercard .mc-ghost { position: absolute; top: 24px; left: var(--gut); margin: 0; font-weight: 500; font-size: clamp(56px, 12cqi, 128px); line-height: 1; letter-spacing: -.02em; color: var(--ghost); pointer-events: none; user-select: none; white-space: nowrap; }\n.own-mastercard .mc-ghost-right { left: auto; right: var(--gut); }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 44px; padding: 0 26px; border-radius: 20px; cursor: pointer;\n  font-family: var(--font); font-size: 16px; font-weight: 500; letter-spacing: -.02em;\n  text-decoration: none; border: 1.5px solid transparent; transition: transform .12s ease, opacity .15s;\n}\n.own-mastercard .mc-btn:active { transform: scale(.97); }\n.own-mastercard .mc-btn-ink { background: var(--ink); color: var(--cream); border-color: var(--ink); }\n.own-mastercard .mc-btn-ghost { background: var(--white); color: var(--ink); border-color: var(--ink); font-weight: 450; }\n.own-mastercard .mc-btn-lg { height: 52px; padding: 0 34px; }\n.own-mastercard .mc-btn-block { width: 100%; }\n\n/* ── nav ─────────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px;\n  max-width: 1200px; margin: 24px auto 0; padding: 8px 12px 8px 24px;\n  border-radius: 999px; background: var(--white); box-shadow: var(--nav-shadow);\n}\n.own-mastercard .mc-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); }\n.own-mastercard .mc-orbit { position: relative; width: 34px; height: 22px; display: inline-block; }\n.own-mastercard .mc-orbit i { position: absolute; top: 0; width: 22px; height: 22px; border-radius: 50%; background: var(--signal-light); }\n.own-mastercard .mc-orbit i:nth-child(1) { left: 0; background: #eb001b; opacity: .9; }\n.own-mastercard .mc-orbit i:nth-child(2) { right: 0; background: #f79e1b; opacity: .9; }\n.own-mastercard .mc-logo-word { font-weight: 500; font-size: 18px; letter-spacing: -.02em; }\n.own-mastercard .mc-nav-links { display: flex; align-items: center; gap: 40px; margin-left: 12px; }\n.own-mastercard .mc-nav-links a { color: var(--ink); text-decoration: none; font-size: 16px; font-weight: 500; letter-spacing: -.03em; }\n.own-mastercard .mc-nav-links a:hover { color: var(--signal); }\n.own-mastercard .mc-nav-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }\n.own-mastercard .mc-cta { display: inline-flex; align-items: center; height: 44px; padding: 0 24px; border-radius: 20px; background: var(--ink); color: var(--cream); text-decoration: none; font-size: 15px; font-weight: 500; letter-spacing: -.02em; }\n.own-mastercard .mc-search { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; border: 1.5px solid var(--ink); background: var(--white); cursor: pointer; }\n.own-mastercard .mc-search svg { width: 18px; height: 18px; fill: none; stroke: var(--ink); stroke-width: 2; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-hero { padding: clamp(28px, 4cqi, 48px) var(--gut) 0; }\n.own-mastercard .mc-hero-frame {\n  position: relative; height: clamp(320px, 46cqi, 520px); border-radius: 40px; overflow: hidden;\n  background: radial-gradient(120% 130% at 18% 12%, #3a3f4a 0%, #1c1f26 46%, #101216 100%);\n  box-shadow: var(--halo);\n  display: flex; align-items: flex-end; padding: clamp(20px, 3cqi, 40px);\n}\n.own-mastercard .mc-hero-glass { display: flex; gap: clamp(20px, 4cqi, 56px); align-items: flex-end; width: 100%; }\n.own-mastercard .mc-hero-bars { display: flex; align-items: flex-end; gap: 14px; height: 190px; flex: 1; max-width: 520px; }\n.own-mastercard .mc-hero-bars span { flex: 1; height: var(--h); border-radius: 999px 999px 6px 6px; background: linear-gradient(180deg, rgba(243,115,56,.95), rgba(243,115,56,.35)); }\n.own-mastercard .mc-hero-bars span:nth-child(even) { background: linear-gradient(180deg, rgba(255,255,255,.85), rgba(255,255,255,.2)); }\n.own-mastercard .mc-hero-side { display: grid; grid-template-columns: auto auto; gap: 6px 14px; align-items: baseline; color: var(--white); }\n.own-mastercard .mc-hero-side b { font-weight: 500; font-size: clamp(24px, 2.6cqi, 34px); letter-spacing: -.02em; }\n.own-mastercard .mc-hero-side span { font-size: 13px; color: rgba(255,255,255,.7); }\n.own-mastercard .mc-hero-copy { padding: 40px 0 8px; max-width: 900px; }\n.own-mastercard .mc-hero-copy .mc-h1 { margin-top: 14px; }\n.own-mastercard .mc-hero-two { display: grid; grid-template-columns: 1.4fr auto; gap: 32px; align-items: center; margin-top: 24px; }\n.own-mastercard .mc-lead { color: var(--charcoal); }\n.own-mastercard .mc-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n\n/* ── services ────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-services { position: relative; padding: clamp(72px, 10cqi, 160px) var(--gut) clamp(48px, 6cqi, 96px); overflow: hidden; }\n.own-mastercard .mc-serv-copy { position: relative; z-index: 2; max-width: 560px; margin: 40px 0 56px; }\n.own-mastercard .mc-serv-copy .mc-h2 { margin-top: 14px; }\n.own-mastercard .mc-serv-grid { position: relative; z-index: 2; display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(24px, 3cqi, 48px); align-items: start; }\n.own-mastercard .mc-offset { margin-top: 64px; }\n.own-mastercard .mc-portrait-card { max-width: 340px; margin: 0 auto; text-align: left; }\n.own-mastercard .mc-portrait { position: relative; width: clamp(220px, 22cqi, 300px); height: clamp(220px, 22cqi, 300px); border-radius: 50%; margin: 0 auto 24px; }\n.own-mastercard .mc-portrait-a { background: radial-gradient(70% 70% at 35% 30%, #ffd9a8 0%, #f37338 52%, #cf4500 100%); }\n.own-mastercard .mc-portrait-b { background: radial-gradient(70% 70% at 40% 35%, #cfe0ff 0%, #7d9bd8 55%, #3a5aa0 100%); }\n.own-mastercard .mc-portrait-c { background: radial-gradient(70% 70% at 40% 35%, #ffe6b0 0%, #f2b23a 55%, #b56a00 100%); }\n.own-mastercard .mc-satellite { position: absolute; right: 4%; bottom: 4%; width: 54px; height: 54px; border-radius: 50%; background: var(--white); display: grid; place-items: center; text-decoration: none; box-shadow: 0 6px 16px -6px rgba(0,0,0,.3); transition: transform .2s ease; }\n.own-mastercard .mc-satellite:hover { transform: scale(1.08); }\n.own-mastercard .mc-satellite svg { width: 20px; height: 20px; fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }\n.own-mastercard .mc-portrait-card .mc-h3 { margin-top: 8px; max-width: 24ch; }\n.own-mastercard .mc-orbits { position: absolute; inset: 0; z-index: 1; pointer-events: none; }\n.own-mastercard .mc-orbits svg { width: 100%; height: 100%; }\n.own-mastercard .mc-orbits path { fill: none; stroke: var(--signal-light); stroke-width: 1.5; stroke-linecap: round; stroke-dasharray: 1 9; }\n\n/* ── stories ─────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-stories { position: relative; padding: clamp(56px, 8cqi, 120px) var(--gut); overflow: hidden; }\n.own-mastercard .mc-stories-head { position: relative; z-index: 2; max-width: 560px; margin: 40px 0 40px; }\n.own-mastercard .mc-stories-head .mc-h2 { margin-top: 14px; }\n.own-mastercard .mc-stories-grid { position: relative; z-index: 2; display: grid; grid-template-columns: 1fr 1.2fr; gap: clamp(24px, 3cqi, 48px); align-items: stretch; }\n.own-mastercard .mc-stat-card { background: var(--lifted); border-radius: 40px; padding: clamp(28px, 3cqi, 40px); display: grid; gap: 22px; align-content: start; }\n.own-mastercard .mc-stat-row { display: grid; gap: 2px; padding-bottom: 18px; border-bottom: 1px solid var(--dust); }\n.own-mastercard .mc-stat-row:last-child { border-bottom: 0; padding-bottom: 0; }\n.own-mastercard .mc-stat-row b { font-weight: 500; font-size: clamp(34px, 4cqi, 52px); letter-spacing: -.02em; line-height: 1; }\n.own-mastercard .mc-stat-row span { font-size: 14px; color: var(--slate); }\n.own-mastercard .mc-quote { margin: 0; background: var(--white); border-radius: 40px; padding: clamp(28px, 3.4cqi, 48px); display: flex; flex-direction: column; justify-content: center; }\n.own-mastercard .mc-quote blockquote p { margin: 0; font-weight: 500; font-size: clamp(22px, 2.4cqi, 30px); line-height: 1.2; letter-spacing: -.02em; }\n.own-mastercard .mc-quote figcaption { margin-top: 24px; display: grid; gap: 2px; }\n.own-mastercard .mc-quote figcaption b { font-weight: 500; }\n.own-mastercard .mc-quote figcaption span { color: var(--slate); font-size: 14px; }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-pricing { padding: clamp(56px, 8cqi, 120px) var(--gut); }\n.own-mastercard .mc-pricing-head { max-width: 620px; margin: 0 auto 48px; text-align: center; }\n.own-mastercard .mc-pricing-head .mc-h2 { margin-top: 14px; }\n.own-mastercard .mc-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; align-items: stretch; max-width: 1080px; margin: 0 auto; }\n.own-mastercard .mc-tier { position: relative; background: var(--white); border-radius: 40px; padding: 36px 32px; display: flex; flex-direction: column; }\n.own-mastercard .mc-tier-featured { background: var(--lifted); box-shadow: var(--halo); }\n.own-mastercard .mc-tier-flag { position: absolute; top: 20px; right: 24px; font-size: 12px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--signal); }\n.own-mastercard .mc-tier-price { font-weight: 500; font-size: clamp(34px, 4cqi, 48px); letter-spacing: -.02em; margin: 8px 0 20px; }\n.own-mastercard .mc-tier-price span { font-size: 15px; font-weight: 450; color: var(--slate); }\n.own-mastercard .mc-tier-list { list-style: none; display: grid; gap: 12px; margin: 0 0 28px; padding: 0; flex: 1; }\n.own-mastercard .mc-tier-list li { position: relative; padding-left: 26px; font-size: 15px; color: var(--charcoal); }\n.own-mastercard .mc-tier-list li::before { content: ''; position: absolute; left: 0; top: 6px; width: 14px; height: 8px; border-left: 2px solid var(--signal); border-bottom: 2px solid var(--signal); transform: rotate(-45deg); }\n\n/* ── cta ──────────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-cta { margin: 0 var(--gut); background: var(--ink); color: var(--cream); border-radius: 40px; padding: clamp(48px, 7cqi, 96px) 32px; text-align: center; display: grid; gap: 28px; justify-items: center; }\n.own-mastercard .mc-cta .mc-h2 { color: var(--cream); }\n.own-mastercard .mc-cta .mc-btn-ink { background: var(--cream); color: var(--ink); border-color: var(--cream); }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-mastercard .mc-foot { margin-top: clamp(56px, 8cqi, 120px); background: var(--ink); color: var(--white); padding: clamp(48px, 6cqi, 100px) var(--gut) clamp(40px, 5cqi, 80px); }\n.own-mastercard .mc-foot-head { font-weight: 500; font-size: clamp(28px, 3.6cqi, 44px); letter-spacing: -.02em; line-height: 1.1; max-width: 20ch; margin-bottom: 48px; }\n.own-mastercard .mc-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }\n.own-mastercard .mc-foot-col h3 { font-size: 13px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--dust); margin-bottom: 16px; }\n.own-mastercard .mc-foot-col a { display: block; color: var(--white); text-decoration: none; font-size: 14px; font-weight: 450; margin-bottom: 12px; }\n.own-mastercard .mc-foot-col a:hover { color: var(--signal-light); }\n.own-mastercard .mc-foot-bottom { display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-top: 56px; padding-top: 24px; border-top: 1px solid rgba(255,255,255,.25); font-size: 13px; }\n.own-mastercard .mc-foot-small { display: flex; gap: 20px; }\n.own-mastercard .mc-foot-small a { color: var(--dust); text-decoration: none; }\n.own-mastercard .mc-foot-small a:hover { color: var(--white); }\n.own-mastercard .mc-lang { display: inline-flex; align-items: center; gap: 8px; height: 40px; padding: 0 20px; border-radius: 999px; background: transparent; color: var(--white); border: 1px solid rgba(255,255,255,.4); font-family: var(--font); font-size: 13px; cursor: pointer; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-mastercard .mc-nav-links { display: none; }\n  .own-mastercard .mc-serv-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-mastercard .mc-offset { margin-top: 0; }\n  .own-mastercard .mc-portrait-card:last-child { grid-column: 1 / -1; }\n  .own-mastercard .mc-stories-grid { grid-template-columns: 1fr; }\n  .own-mastercard .mc-tiers { grid-template-columns: 1fr 1fr; }\n  .own-mastercard .mc-tier:last-child { grid-column: 1 / -1; }\n}\n@container frame (max-width: 760px) {\n  .own-mastercard .mc-nav { top: 10px; margin: 12px 12px 0; padding: 6px 10px 6px 16px; gap: 10px; }\n  .own-mastercard .mc-cta { margin: 0 12px; }\n  .own-mastercard .mc-hero { padding-left: 12px; padding-right: 12px; }\n  .own-mastercard .mc-services, .own-mastercard .mc-stories, .own-mastercard .mc-pricing, .own-mastercard .mc-foot { padding-left: 16px; padding-right: 16px; }\n  .own-mastercard .mc-ghost { font-size: 56px; }\n  .own-mastercard .mc-hero-two { grid-template-columns: 1fr; gap: 20px; }\n  .own-mastercard .mc-serv-grid, .own-mastercard .mc-tiers { grid-template-columns: 1fr; }\n  .own-mastercard .mc-portrait-card:last-child, .own-mastercard .mc-tier:last-child { grid-column: auto; }\n  .own-mastercard .mc-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-mastercard .mc-foot-grid { grid-template-columns: 1fr; }\n  .own-mastercard .mc-orbits { display: none; }\n  .own-mastercard .mc-nav-right .mc-cta { display: none; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-mastercard *, .own-mastercard *::before, .own-mastercard *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Mastercard own-layout behaviour ═══════════════════════════
   Registers window.OWN_LAYOUTS['mastercard'].init(root). The layout is largely
   static; the one dynamic affordance is the pricing language pill, which cycles
   a couple of sample locales. Returns a cleanup removing the listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['mastercard'] = {
    init: function (root) {
      var lang = root.querySelector('.mc-lang');
      var locales = ['English \u00B7 PH', 'English \u00B7 UK', 'Fran\u00E7ais \u00B7 FR'];
      var i = 0;

      function onClick() {
        i = (i + 1) % locales.length;
        lang.textContent = locales[i];
      }
      if (lang) lang.addEventListener('click', onClick);

      return function cleanup() {
        if (lang) lang.removeEventListener('click', onClick);
      };
    }
  };
})();
